sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parent))
from gongbi_training.runtime import configure,LAB
configure()
import numpy as np
from PIL import Image,ImageDraw,ImageFont
from guohua_priority_check_20261116 import ROOT,SEG,FRESH,read,write,sha,test_gate
from gongbi_training.scene_objects import scene_metrics
def main():
 res=read(ROOT/'results.json');p=res['protocol'];ds=read(ROOT/'test_manifest.json');assert sha(SEG/'mapping_fixed.pt')==p['segmentation_sha256'];assert sha(SEG/'results.json')==p['segmentation_results_sha256'];assert sha(FRESH/'predictions.json')==p['frozen_style_predictions_sha256'];assert sha(FRESH/'test_manifest.json')==p['style_manifest_sha256'];assert sha(Path(__file__).with_name('guohua_priority_check_20261116.py'))==p['script_sha256'];assert sha(Path(__file__).resolve().parents[1]/'gongbi_training/rock_candidate_gate.py')==p['gate_module_sha256'];(ROOT/'views').mkdir(exist_ok=True);colors=np.array([[232,235,225],[183,134,75],[65,149,91],[145,157,170]],'uint8');records=[]
 for r in ds['records']:
  z=np.load(ROOT/'predictions'/(r['id']+'.npz'));pred=z['prediction'];target=np.array(Image.open(r['target']));assert scene_metrics(target,pred)['confusion']==next(x for x in res['new_work_partition'] if x['id']==r['id'])['scores']['confusion'];Image.open(r['image']).save(ROOT/'views'/(r['id']+'_input.png'));ref=np.full((*target.shape,3),[248,242,224],dtype='uint8');ref[target!=255]=colors[target[target!=255]];Image.fromarray(ref).save(ROOT/'views'/(r['id']+'_reference.png'));Image.fromarray(colors[pred]).save(ROOT/'views'/(r['id']+'_prediction.png'));gate=np.full_like(ref,[225,228,219]);gate[z['rock_candidate']]=[62,100,180];Image.fromarray(gate).save(ROOT/'views'/(r['id']+'_gate.png'));records.append(dict(id=r['id'],work_group=r['work_group'],input='views/'+r['id']+'_input.png',reference='views/'+r['id']+'_reference.png',prediction='views/'+r['id']+'_prediction.png',gate='views/'+r['id']+'_gate.png'))
 style=[]
 for r in res['style_records']:
  Image.open(r['image']).save(ROOT/'views'/(r['id']+'_input.png'));z=np.load(ROOT/'predictions'/(r['id']+'.npz'));Image.fromarray(colors[z['prediction']]).save(ROOT/'views'/(r['id']+'_context_objects.png'));q=dict(r);q['input']='views/'+r['id']+'_input.png';q['objects']='views/'+r['id']+'_context_objects.png';style.append(q)
 font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',17);board=Image.new('RGB',(1280,4*350+65),'#f4f1e8');d=ImageDraw.Draw(board)
 for i,r in enumerate(records):
  for j,(k,t) in enumerate([('input','预留作品原图'),('reference','源粗场景参考'),('prediction','冻结分区候选'),('gate','蓝=可送皴法分支的岩区候选')]):
   im=Image.open(ROOT/r[k]);im.thumbnail((308,280));board.paste(im,(j*320+5,i*350+35));d.text((j*320+5,i*350+5),t,font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',14),fill='#294735')
  d.text((5,i*350+320),r['id'],font=font,fill='#79523a')
 d.text((5,4*350+7),'候选图不是完整石头实例、笔画或皴法真值；未通过候选不等于没有真实线条。',font=font,fill='#79523a');board.save(ROOT/'partition_to_cunfa.jpg',quality=94)
 errors=[r for r in style if r['route']['eligible_for_exploratory_cunfa'] and not r['source_label_agreement']];assert len(errors)==6
 errorboard=Image.new('RGB',(960,3*330+60),'#f4f1e8');ed=ImageDraw.Draw(errorboard)
 for i,r in enumerate(errors):
  im=Image.open(ROOT/r['input']);scale=min(220/im.width,235/im.height);im=im.resize((round(im.width*scale),round(im.height*scale)),Image.Resampling.NEAREST);x=(i%2)*480;y=(i//2)*330;errorboard.paste(im,(x+5,y+30));ed.text((x+5,y+4),r['id'],font=font,fill='#294735');ed.text((x+235,y+50),'来源暂标：'+r['source_label'],font=font,fill='#294735');ed.text((x+235,y+95),'旧分类器：'+r['raw_style_prediction'],font=font,fill='#875238');ed.text((x+235,y+140),'岩区候选覆盖：'+str(round(r['route']['rock_candidate_fraction']*100,1))+'%',font=font,fill='#294735');ed.text((x+5,y+280),'山石候选通过，但皴法分类仍与来源暂标不符',font=font,fill='#875238')
 ed.text((5,3*330+5),'来源局部标签未经专家确认；这些错例不自动成为新训练真值。',font=font,fill='#875238');errorboard.save(ROOT/'remaining_style_errors.jpg',quality=94)
 write('style_failure_review_queue.json',dict(records=[dict(id=r['id'],work_id=r['work_id'],image=r['image'],source_url=r['source_url'],provisional_source_style=r['source_label'],frozen_prediction=r['raw_style_prediction'],rock_candidate_fraction=r['route']['rock_candidate_fraction'],review_tasks=['confirm local rock and cun group','verify local method rather than work-wide title','annotate visible mark shape and group flow','preserve mixed/unknown and do not infer physical pressure'],training_eligible=False,automatic_prediction_is_not_reference=True) for r in errors],new_expert_labels=0,new_classifier_training=False))
 write('report_data.json',dict(records=records,partition=res['new_work_partition'],style=style,summary=res['style_summary']))
 check=test_gate();check.update(all_artifact_hashes_match=True,new_work_metrics_recomputed=True,new_partition_cases=4,opened_work_groups=2,known_style_diagnostics=13,all_rejected_cases_visible=True,remaining_six_style_errors_preserved=True,style_predictions_unchanged=True,gate_is_not_object_validation=True,no_new_training=True,tree_skill_training=False,robot_connected=False);write('verification.json',check)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>四项目标：分区与皴法入口检查</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#294735;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:29px}.note{padding:15px;background:#fff8e8;border-left:5px solid #b77f45}.warn{color:#875238}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{min-width:0;background:#fffdf8;border:1px solid #d4d9cb;padding:10px}img{display:block;max-width:100%;height:auto;margin:auto}select{width:650px;max-width:100%;padding:8px;font:inherit}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #d0d6c8}td img{max-height:150px}a{color:#236b61}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:24px}}</style><main><small>2026-11-16 · 四项目标的联动检查 · 无新模型训练</small><h1>分区服务于皴法，不把整体分类分数当最终目标</h1><p class="note"><b>分区权重已冻结，开始检查它对皴法辨识是否有用。</b>启用两组此前预留作品的4张图作未参与训练的检查；同时把分区接到13个已有给定皴法局部。新图仍有关键误分；13个局部中11个通过岩区候选筛查，但6个分类错例全部仍在，说明不能靠继续调分区来解决皴法辨识。</p><h2>1. 四项目标的当前状态</h2><div class="scroll"><table><tr><th>用户目标</th><th>本轮落实</th><th>尚缺的能力</th></tr><tr><td>具体皴法辨识</td><td>接入对象候选检查，保留全部6个分类错例及逐局部来源复核队列</td><td>完整山石上下文、可见笔形／笔组依据、具体皴法或未知；尚无新辨识模型</td></tr><tr><td>区分山石与树木</td><td>冻结候选，检验未训练作品、加入待定区域输出</td><td>树石交界仍有错分，未正式通过；只围绕影响皴法的关键错例回修</td></tr><tr><td>树木画法训练</td><td>保留主干→主枝→枝叶依赖与对象角色约束</td><td>前两项通过后再启动；树木画法训练保持关闭</td></tr><tr><td>完整提取、层次笔序与同风格创作</td><td>保留已有认可绘画基线，约束未知不得直接成为绘画动作</td><td>完整石头实例、轮廓／皴笔归属、完整笔触、技能与真实墨迹；未实现自主创作</td></tr></table></div><h2>2. 两组预留作品的首次对象检查</h2><p>冻结权重及置信阈值后，在每组预留路径中固定取字典序首尾两张，共4张。来源为同一CLPD，原作者及原作身份未独立认证，源参考是粗语义掩码，不能称专家验收。两个完整作品组现已启用检查，未下载的其余裁剪也不能在以后被算作新独立作品。</p><select id="case"></select><p id="scope"></p><div class="grid"><div class="card"><b>原图</b><img id="input"></div><div class="card"><b>源粗参考</b><img id="reference"></div><div class="card"><b>模型直接分区</b><img id="prediction"></div><div class="card"><b>岩区候选，非皴笔</b><img id="gate"></div></div><p id="refnote">源粗参考，无完整对象边界真值。蓝色是送往皴法探索分支的像素候选，不是确认山石、独立石块实例或完整笔画；其他位置只是此分支不接收，原始图与轨迹不删除。</p><div class="scroll"><table><thead><tr><th>图像</th><th>原山石精度／召回</th><th>候选山石精度／召回</th><th>候选占已标像素</th><th>树木误进入候选比例</th></tr></thead><tbody id="metrics"></tbody></table></div><p>候选阈值预先固定：山石softmax≥0.75、与竞争类别差≥0.20；该置信值未作概率校准。候选精度提高会牺牲召回，必须同时看两者。仍可能有高置信错分，不能声称已阻止所有树叶进入皴法。</p><details><summary>展开四图总览</summary><img src="partition_to_cunfa.jpg"></details><h2>3. 皴法检查：为什么不能只继续优化分区</h2><p class="note" id="summary"></p><p>13个局部均来自此前已查看的来源暂标案例，并非本轮新盲测。局部位置与2.5倍上下文来自原复核框，不是模型全图自主找出的完整皴笔。旧披麻／斧劈分类器输出和边距完全未改；只有岩区候选不足时保留待定。筛选后的对应比例是选择效应，不是新分类准确率。</p><div class="scroll"><table><thead><tr><th>给定局部</th><th>来源暂标</th><th>旧分类器候选</th><th>岩区候选比例／路由</th><th>最终状态</th></tr></thead><tbody id="styles"></tbody></table></div><p>所有最终皴法仍为待核查；候选不自动变成真值或训练标签。给出类别名字、通过岩区筛查、或写出绘画解释，都不能证明已理解皴法。</p><h2>4. 岩区候选通过后仍存在的六个分类错例</h2><img src="remaining_style_errors.jpg"><p>来源标签基于作品说明和助手局部检查，未经专家逐局部确认。下一步重点核查它们真实的笔形、用锋可见证据、笔组排列与混合情况；不能直接把分类器预测或作品标题当训练答案。</p><h2>5. 后续工作集中在四项主线</h2><p>分区只回修树叶进岩区、主山体漏分、关键交界等错误，不为细分其他杂类单独追加训练。皴法方向继续独立推进完整山石—皴笔—笔组参考及类别／未知辨识。前两项通过后再训练松树枝干和叶法，最后整合对象主次、先轮廓后皴笔、一块完成再切换、同风格生成与实机笔触。</p><p>连通像素不等于一块石头实例，语义区域也不是线条。对象置信筛查不会作为完整线条提取的删除规则。当前仍未替换认可绘画版本，也未连接机械臂。</p><p><a href="protocol.json">检查前冻结协议</a> · <a href="test_manifest.json">新图来源与分组</a> · <a href="results.json">完整结果和全部拒绝案例</a> · <a href="style_failure_review_queue.json">六个皴法错例复核队列</a> · <a href="verification.json">验证记录</a></p></main><script>let D;const $=s=>document.getElementById(s),pct=x=>x===null?'无参考':(x*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];for(let k of ['input','reference','prediction','gate'])$(k).src=r[k];$('scope').textContent=r.id+' / '+r.work_group}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of d.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').onchange=show;show();for(let r of d.partition){let a=r.raw_rock,b=r.candidate_rock,tr=document.createElement('tr');tr.innerHTML='<td>'+r.id+'</td><td>'+pct(a.rock_precision)+' / '+pct(a.rock_recall)+'</td><td>'+pct(b.rock_precision)+' / '+pct(b.rock_recall)+'</td><td>'+pct(b.known_pixel_coverage)+'</td><td>'+pct(b.tree_admitted_fraction)+'</td>';$('metrics').append(tr)}let s=d.summary;$('summary').textContent='原13局部与来源暂标一致：'+pct(s.raw_agreement)+'；保留'+s.retained_regions+'/'+s.original_regions+'个，覆盖'+pct(s.coverage)+'，保留部分一致比例'+pct(s.retained_agreement)+'。全部6个原分类错例仍被保留；没有证明分类改善。';for(let r of d.style){let tr=document.createElement('tr'),td=document.createElement('td'),im=document.createElement('img');im.src=r.input;td.append(im);td.append(document.createTextNode(r.id));tr.append(td);for(let text of [r.source_label,r.raw_style_prediction,pct(r.route.rock_candidate_fraction)+' / '+(r.route.eligible_for_exploratory_cunfa?'可作探索候选':'待定，不接收'),'未知；未确认皴法']){let q=document.createElement('td');q.textContent=text;tr.append(q)}$('styles').append(tr)}window.reportReady=true});</script></html>'''
 (ROOT/'index.html').write_text(page,encoding='utf8')
 server=Path(__file__).with_name('serve_guohua_objects_v2_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_priority_check_20261116');a=server.index('ALLOWED={');b=server.index('\nALLOWED.update',a);server=server[:a]+"ALLOWED={'index.html','partition_to_cunfa.jpg','remaining_style_errors.jpg','report_data.json','protocol.json','test_manifest.json','results.json','style_failure_review_queue.json','verification.json'}"+server[b:];(ROOT/'serve_report.py').write_text(server.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8')
 checker=Path(__file__).with_name('check_guohua_objects_v2_view_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_priority_check_20261116').replace(')==27',')==4').replace('range(27)','range(4)').replace(')==6',')==4').replace(';assert js("document.querySelectorAll(\'#works tr\').length")==4','').replace('work_metrics_four_rows=True,','').replace('all27_observations_switch_and_load','all4_observations_switch_and_load').replace('metrics_six_rows','metrics_four_rows').replace("['protocol.json','results.json','selection_before_download.json','source_checked_cunfa_concepts.json','verification.json']","['protocol.json','results.json','test_manifest.json','style_failure_review_queue.json','verification.json']")
 checker=checker.replace("assert requests.post(url,timeout=5).status_code==405","assert js('document.querySelectorAll(\"#styles tr\").length')==13\n assert requests.post(url,timeout=5).status_code==405")
 (ROOT/'check_report.py').write_text(checker.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8');print(json.dumps(check),flush=True)
if __name__=='__main__':main()
